CREATE TABLE invoices (id TEXT PRIMARY KEY, invoice_number TEXT NOT NULL UNIQUE, status TEXT NOT NULL CHECK(status IN ('COMPLETED','CANCELLED')), subtotal_paise INTEGER NOT NULL CHECK(subtotal_paise>=0), discount_paise INTEGER NOT NULL CHECK(discount_paise>=0), tax_paise INTEGER NOT NULL CHECK(tax_paise>=0), total_paise INTEGER NOT NULL CHECK(total_paise>=0), customer_name TEXT, customer_phone TEXT, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE invoice_items (id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL REFERENCES invoices(id), variant_id TEXT NOT NULL REFERENCES product_variants(id), product_name TEXT NOT NULL, sku TEXT NOT NULL, size TEXT NOT NULL, colour TEXT NOT NULL, unit_price_paise INTEGER NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), discount_paise INTEGER NOT NULL CHECK(discount_paise>=0), tax_paise INTEGER NOT NULL CHECK(tax_paise>=0), line_total_paise INTEGER NOT NULL CHECK(line_total_paise>=0));
CREATE TABLE payments (id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL REFERENCES invoices(id), method TEXT NOT NULL CHECK(method IN ('CASH','UPI','CARD')), amount_paise INTEGER NOT NULL CHECK(amount_paise>0), created_at TEXT NOT NULL);
CREATE INDEX invoice_created ON invoices(created_at);
CREATE INDEX invoice_item_variant ON invoice_items(variant_id);
